  Lu = `Съотнесено съдържание: %2$s.`,
  Ru = `Прегледът от Valve се изисква, преди задаването на тази страница като пусната да стане възможно.`,
  zu = `Това събитие за разпродажба е висящо за одобрение от Valve`,
  Bu = `Моля, използвайте бутона отдясно, така че да подадете своята страница за преглеждане поне 7 дни преди желаната от Вас дата на публикуване, за да подсигурите достатъчно време за преглед/одобрение и всякакви необходими промени.`,
  Vu = `Steam екипът ще се свърже с Вас чрез билет на Steamworks поддръжката, ако се изискват някакви промени по Вашата страница. Можете да преглеждате билета от Steamworks поддръжката и да добавяте коментари, ако е необходимо, като кликнете върху бутона вдясно.`,
  Hu = `Маркирането на страницата като „одобрена“ ще позволи на партньора да публикува и пусне разпродажбата`,
  Uu = `Заявка за преглед…`,
  Wu = `Заявка за преглед`,
  Gu = `Създава билет със заявка за преглед за одобрение за публикуване на страница за разпродажба. Направете това, когато страницата Ви за разпродажба разполага с финално художествено творчество и включва всички игри, които искате да отличите.`,
  Ku = `Това ще създаде билет към Steamworks поддръжката, изискващ преглед от Valve на страницата Ви за разпродажба. Това трябва да бъде правено само след като сте финализирали художественото творчество и съобщенията, а списъкът от игри е завършен.`,
  qu = `Моля, уверете се, че заглавието и целта на събитието Ви са ясно описани в близо до горната част на страницата. При изложенията е възможно да се нуждаете от текстова секция в горната част на Вашата страница. Така ще можете да опишете какво представлява изложението Ви и как работи.`,
  Ju = `Страницата за разпродажбата ще бъде заключена, след като бъде прегледана. Ако е нужно да правите промени след прегледа или щом събитието стартира, моля, напишете в коментара какво включват тези промени и защо не са били завършени преди прегледа.`,
  Yu = `Незадължително — Инф., която желаете да включите за проверяващите.`,
  Xu = `Изберете партньори, чиито членове също могат да имат достъп до билета за заявката`,
  Zu = `Незадължително — Ако е избрано, други партньорски членове могат да имат достъп и да откликват на билета. По подразбиране само Вие можете да четете, обновявате и откликвате на създадения билет.`,
  Qu = `Неуспешно създаване на билет, моля, опитайте по-късно`,
  $u = `Невъзможно създаване на нов билет. Вече съществува билет от този тип. Моля, завършете прегледа на другата Ви страница за разпродажба, преди да подадете тази. Или обновете съществуващия билет, за да включите прегледа и на тази страница.`,
  ed = `Билетът е създаден успешно!`,
  td = `Вижте билет за рецензия…`,
  nd = `Страницата Ви е одобрена и готова за публикуване`,
  rd = `Превключете към раздела „Публикуване“ за процеса по публикуване.`,
  id = `Уверете се, че сте проверили повторно настройките за видимостта по-долу, преди да публикувате.`,
  ad = `Игра, изключена от изобразяване спрямо Вашите <1>предпочитания в магазина</1>.`,
  od = `Пакет, изключен от изобразяване спрямо Вашите <1>предпочитания в магазина</1>.`,
  sd = `Комплект, изключен от изобразяване спрямо Вашите <1>предпочитания в магазина</1>.`,
  cd = `+ Списък с желания`,
  ld = `В списъка Ви с желания`,
