  dd = `Добавяне към списъка Ви с желания`,
  fd = `Добавяйте към списъка Ви с желания. Получавайте известия по е-поща, когато пожеланите от Вас артикули се издават или са на разпродажба.`,
  pd = `Този артикул е в списъка Ви с желания. Получавайте известия по е-поща, когато пожеланите от Вас артикули се издават или са на разпродажба.`,
  md = `Грешка при обновяване на списъка с желания`,
  hd = `Натъкнахме се на грешка, добавяйки към списъка Ви с желания. Моля, опитайте отново по-късно:`,
