  Dv = `Публикуване на новини към Steam?`,
  Ov = `Моля, прегледайте следните изисквания, преди да продължите:`,
  kv = `Преглежданата RSS емисия не съответства на текущата настройка. Преди да създадем това ново събитие, е нужно първо да обновим емисията към RSS адреса, използван за прегледа. По подразбиране автоматизацията на RSS емисията ще бъде преустановена. Това може да бъде променено по-късно.`,
  Av = `Създаване/Обновяване на емисията към този адрес за RSS?: „%1$s“`,
  jv = `Неуспешно завършване на създаване/обновяване на емисия и/или действие за публикуване на новини`,
