  Pv = `Това събитие вече съществува в Steam. Бихте ли искали да обновите съдържанието му от RSS артикул? Полезно е, ако съдържанието на RSS артикула се е променило. Това ще премахне всякаква персонализация, направена, използвайки редактора.`,
  Fv = `Моля, изчакайте Steam сървърът да завърши действието.`,
  Iv = `RSS емисията беше обновена успешно`,
  Lv = `Анонсът Ви беше създаден успешно. С цел да го редактирате по-нататък, упътете се насам:`,
