  Jb = `„Правилата и насоките“`,
  Yb = `Моля, опишете какво сте харесали или не относно този продукт и дали го препоръчвате на останалите. Моля, не забравяйте да бъдете учтиви и следвайте %1$s. Изисква се описание, за да публикувате своята препоръка.`,
  Xb = `С публикуването на тази рецензия се съгласявате, че местонахождението, където сте написали тази рецензия, ще бъде споделено с други потребители в „Steam China“ („Steam | Китай“).`,
  Zb = `Позволяване на коментари`,
