  ex = `Ако сте запазили част от хардуерната си информация към Steam, можете да я прикачите към своята рецензия и тя ще бъде показвана на останалите потребители.`,
  tx = `Поставете отметка в това поле, ако този продукт Ви е бил предоставен безплатно. Ще показва „Продуктът е получен безплатно“ редом с рецензията Ви. Ако сте получили допълнителна компенсация за рецензията на тази игра, трябва да разкриете това в текста.`,
