  yS = `Направете заглавието завладяващо и уместно за играчите. Ако това наистина е едно от най-големите обновления за годината, заглавието би трябвало да отразява това вълнение. Избягвайте общи фрази като <1>„Обновление за версия 330.4“</1>. Вместо това, отличете това, което прави обновлението специално.`,
  bS = `Ключовото художествено творчество трябва ясно да излага самото обновление. Недейте просто пак да използвайте стандартното художествено творчество на играта Ви. Играчите трябва незабавно да разпознаят, че това представлява нещо ново и значително.`,
  xS = `Описанието на събитието трябва да бъде внимателно изготвено, за да обясни обновлението и защо то е от значение. Използвайте това като Вашия шанс да върнете потребителите към играта Ви:`,
