  UV = `Некатегоризирани`,
  WV = `Може би е заради завладяващото игрално преживяване или увлекателната история… Добре изпипаните персонажи, безупречният дизайн, или пък пристрастяващата игра в мрежа. Каквато и да е причината, тазгодишният носител на наградата „Най-добра игра за 2020“ е мигновена класика.`,
  GV = `ВР играта на годината не просто имитира обичайната реалност. Тя подобрява реалността, възползвайки се от ВР медията, за да разшири границите на виртуалния свят.`,
  KV = `Тази игра е излязла преди известно време. Екипът отдавна е отминал дебюта на креативното им бебче, но бидейки олицетворение на добрите родители, тези разработчици продължават да обгрижват и поддържат своето творение. До ден-днешен тази игра все още получава ново съдържание след всичките тези години.`,
  qV = `Има някои заглавия, които просто не са същите, когато ги играете сами. Може би е нужно да разполагате с приятел, който да Ви пази гърба. Или пък Ви е нужен приятел, на когото да забиете нож в гърба. Така или иначе, веселието очаква онези, които свикат приятелите си, за да пуснат тази игра.`,
