  XV = `Това е играта, която награждава постоянството и не е за малодушните. Тя е най-трудната игра, която някога сме обичали.`,
  ZV = `Този невъзпят герой заслужава да бъде похвален за изключителното си музикално оформление. Саундтрак и ОЩЕ КАК! `,
  QV = `През някои дни единственото нещо, което ще Ви дойде добре, е игра с особено силен акцент над повествованието. А тази определено ври и кипи в това отношение. Тя е толкова завладяваща, колкото и всяка сапунена опера, а редом с това е фино изпипана като сценарий за престижна теленовела. Брависимо — за това, че е събудила разни чувства у нас!`,
  $V = `Тази игра е противоотрова за напрегнатия ден. Тя върви гладко, релаксираща е, с нея грижите Ви се топят. Тази игра е Вашият Дзен момент.`,
