  JH = `През някои дни единственото нещо, което ще Ви дойде добре, е игра с особено силен акцент над повествованието. А тази определено ври и кипи в това отношение. Тя е толкова завладяваща, колкото и всяка сапунена опера, а редом с това е фино изпипана като сценарий за престижна теленовела. Брависимо — за това, че е събудила разни чувства у нас!`,
  YH = `Тази игра е противоотрова за напрегнатия ден. Тя върви гладко, релаксираща е, с нея грижите Ви се топят. Тази игра е Вашият Дзен момент.`,
  XH = `Тази игра е била толкова добра, че сте искали да я вземете със себе си навсякъде. Така и сте направили! А за щастие качествата, които са я правели достойна за безспирно преиграване на компютъра Ви, са още по-безупречни в движение.`,
