  iU = `Томболата вече приключи, благодарим Ви за участието.`,
  aU = `Томболата вече приключи с %1$s щастливи победители, благодарим Ви за участието.`,
  oU = `Кликнете, за да научите още относно наградите, победителите и правилата.`,
  sU = `Проверявайте пак всеки ден за нов подарък от императора!`,
