  OU = `Част II от IV`,
  kU = `Част III от IV`,
  AU = `Част IV от IV`,
  jU = `Нефритеният император призовал всички създания от своето кралство да се надпреварват до небесния дворец, обявявайки, че първите дванадесет, които пристигнат, ще бъдат удостоени с място на новия му календар.

Умният плъх бил първият, който преминал през реката в божественото владение. Тъй като не бил почитател на плуването, плъхът се повозил връз верния вол. Скачайки развълнувано в градината на императора, точно преди двойката щяла да се доближи, достигайки до брега.

Непоколебимият вол пресякъл реката с лекота. Незаинтересован от резултатите на надпреварата, волът се чувствал задоволен със своята роля в успеха на плъха.`,
  MU = `Независимият тигър пътувал твърде внимателно, за да изпревари вола, мислейки, че е по-добре да пристигне трети, отколкото изобщо да не се класира.

Пъргавият заек скокнал връз някакъв дънер, който далеч не плавал бързо за нейде. Но късметът му се увенчал с успех там, где стратегията не го сторила, и тъй услужлив попътен вятър благополучно ускорил импровизираната лодка по пътя ѝ.

Изгодната позиция на летящия дракон разкрила село в нужда. И тъй, разбира се, драконът спрял, за да помогне, като така дори подарил на заека въздушния порив да прекоси през реката. Честта била далеч по-важна от победата, а драконът считал, че петото място му прилягало добре.`,
  NU = `Потайната змия проявявала малко интерес към влагането на усилия в дълги разстояния, така че незабелязано се увила около предното копито на коня.

Докато конят препускал в галоп към финала, змия се развила. Така стреснала коня за достатъчно дълго, че да се приплъзне в шесто място, а плашливият кон изприпкал в тръс недалеч след нея.`,
  PU = `Козата, маймуната и петелът работили съвместно, но позволили на козата да заяви осмата позиция, тъй като била основата опора на пътешествието им. Веселата маймуна била следващата, а напереният петел пресякъл десети, бидейки горд, че редът е бил справедлив.

Игривото куче повече се интересувало от това да се плацика насам-натам, считайки, че бидейки единадесето било прекрасна размяна за всичкото забавление.

Последна се класирала свинята, която спряла за леко похапване и дрямка. Бидейки достатъчно мъдра, за да знае, че всяко животно щяло да получи своето време за благоразположението на императора.`,
  FU = `Профилните промени ще влязат в сила след преглед`,
